class Stack:
    """栈：支持 push、pop、top 操作。"""

    def __init__(self):
        self._items = []

    def push(self, item):
        """将元素压入栈顶。"""
        self._items.append(item)

    def pop(self):
        """弹出并返回栈顶元素。栈为空时抛出 IndexError。"""
        if not self._items:
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def top(self):
        """返回栈顶元素，但不弹出。栈为空时抛出 IndexError。"""
        if not self._items:
            raise IndexError("top from empty stack")
        return self._items[-1]
